    ModuleActivity(
      id: 'financialAnalysisSimulator',
      tab: ActivityTab.sim,
      kind: ActivityKind.caseScenario,
      title: Bi('Financial Analysis Simulator', 'محاكي التحليل المالي'),
      description: Bi('Apply ratio, trend, and DuPont analysis to real scenarios', 'طبق تحليل النسب والاتجاهات وديبونت على سيناريوهات حقيقية'),
      maxScore: 100,
      instruction: Bi('Apply financial analysis techniques (ratio analysis, horizontal/vertical analysis, DuPont decomposition) to diagnose real-world financial challenges and develop data-driven recommendations.', 'طبّق تقنيات التحليل المالي (تحليل النسب، والتحليل الأفقي/الرأسي، وتفكيك ديبونت) لتشخيص التحديات المالية الواقعية ووضع توصيات مستندة إلى البيانات.'),
      scenarios: [
        CaseScenario(id: 'scenario1', title: Bi('Liquidity Crisis Assessment', 'تقييم أزمة السيولة'), role: Bi('Financial Analyst, Municipal Finance Division', 'محلل مالي، قسم المالية بالبلدية'), overview: Bi('Emirates Regional Municipality is experiencing delays in paying vendor invoices. The CFO suspects a liquidity problem but is unsure whether the root cause is operational inefficiency or structural financial weakness. You are brought in to perform a ratio analysis and diagnose the issue.', 'تواجه بلدية الإمارات الإقليمية تأخيرات في سداد فواتير الموردين. يشتبه المدير المالي في وجود مشكلة سيولة لكنه غير متأكد مما إذا كان السبب الجذري هو عدم الكفاءة التشغيلية أم ضعف مالي هيكلي. يتم استقدامك لإجراء تحليل النسب المالية وتشخيص المشكلة.'), finalSummary: Bi('You successfully diagnosed a liquidity crisis using liquidity and activity ratios, identified overstocked inventory as the root cause, implemented a just-in-time procurement strategy, and communicated the results effectively to stakeholders. This scenario demonstrates the power of ratio analysis to convert financial data into actionable decisions.', 'لقد نجحت في تشخيص أزمة سيولة باستخدام نسب السيولة والنشاط، وحددت المخزون الزائد بوصفه السبب الجذري، وطبّقت استراتيجية شراء في الوقت المناسب، ووصّلت النتائج بفعالية إلى أصحاب المصلحة. يبرهن هذا السيناريو على قوة تحليل النسب في تحويل البيانات المالية إلى قرارات قابلة للتنفيذ.'), steps: [
            CaseStep(id: 'step1', type: CaseStepType.analysis, title: Bi('Calculate Liquidity Ratios', 'حساب نسب السيولة'), description: Bi('Review the municipality\'s balance sheet and calculate key liquidity ratios to assess short-term financial health.', 'راجع قائمة المركز المالي للبلدية واحسب نسب السيولة الرئيسية لتقييم الصحة المالية قصيرة الأجل.'), data: [CaseDatum(Bi('Current Assets', 'الأصول المتداولة'), 'AED 45M'), CaseDatum(Bi('Quick Assets (Cash + Receivables)', 'الأصول السريعة (النقد + الذمم المدينة)'), 'AED 18M'), CaseDatum(Bi('Current Liabilities', 'الالتزامات المتداولة'), 'AED 40M'), CaseDatum(Bi('Accounts Payable (Overdue)', 'الذمم الدائنة (المتأخرة)'), 'AED 12M'), CaseDatum(Bi('Industry Benchmark Current Ratio', 'النسبة المتداولة المعيارية للقطاع'), '2.0')], question: Bi('What do the liquidity ratios reveal about the municipality\'s short-term financial position?', 'ماذا تكشف نسب السيولة عن المركز المالي قصير الأجل للبلدية؟'), options: [
                CaseOption(Bi('Current Ratio is adequate (1.13), but Quick Ratio is weak (0.45) - the issue is tied up in slow-moving inventory', 'النسبة المتداولة كافية (1.13)، لكن النسبة السريعة ضعيفة (0.45) - المشكلة محتجزة في مخزون بطيء الحركة'), isCorrect: true, feedback: Bi('Correct! Current Ratio = 45M / 40M = 1.13 (below the 2.0 benchmark). Quick Ratio = 18M / 40M = 0.45 (critically low). The AED 27M gap between current and quick assets suggests inventory or prepaid expenses are tying up cash.', 'صحيح! النسبة المتداولة = 45M / 40M = 1.13 (أقل من المعيار البالغ 2.0). النسبة السريعة = 18M / 40M = 0.45 (منخفضة بشكل حرج). الفجوة البالغة AED 27M بين الأصول المتداولة والأصول السريعة تشير إلى أن المخزون أو المصروفات المدفوعة مقدماً تحتجز النقد.')),
                CaseOption(Bi('Both ratios are healthy - the payment delays must be due to poor process management', 'كلتا النسبتين صحية - لا بد أن تأخيرات السداد ناتجة عن سوء إدارة العمليات'), feedback: Bi('The ratios are not healthy. A Quick Ratio of 0.45 means only 45 fils in liquid assets for every dirham of current debt - far below the 1.0 minimum threshold.', 'النسب ليست صحية. النسبة السريعة البالغة 0.45 تعني وجود 45 فلساً فقط من الأصول السائلة مقابل كل درهم من الدين المتداول - أقل بكثير من الحد الأدنى البالغ 1.0.')),
                CaseOption(Bi('The municipality is insolvent and should consider bankruptcy', 'البلدية معسرة وينبغي أن تفكر في إشهار الإفلاس'), feedback: Bi('Liquidity problems do not equal insolvency. The municipality has AED 45M in current assets, it just needs to convert them to cash faster. Solvency analysis requires examining long-term debt and equity.', 'مشكلات السيولة لا تعادل الإعسار. تمتلك البلدية AED 45M من الأصول المتداولة، وكل ما تحتاجه هو تحويلها إلى نقد بشكل أسرع. يتطلب تحليل الملاءة فحص الديون طويلة الأجل وحقوق الملكية.')),
            ]),
            CaseStep(id: 'step2', type: CaseStepType.analysis, title: Bi('Analyze Activity Ratios', 'تحليل نسب النشاط'), description: Bi('You identified that non-liquid current assets are the problem. Now examine activity ratios to determine which asset class is causing the bottleneck.', 'لقد حددت أن الأصول المتداولة غير السائلة هي المشكلة. افحص الآن نسب النشاط لتحديد فئة الأصول التي تسبب الاختناق.'), data: [CaseDatum(Bi('Inventory (Maintenance Supplies)', 'المخزون (لوازم الصيانة)'), 'AED 15M'), CaseDatum(Bi('Annual Maintenance Expense', 'مصروف الصيانة السنوي'), 'AED 30M'), CaseDatum(Bi('Receivables', 'الذمم المدينة'), 'AED 10M'), CaseDatum(Bi('Annual Revenue', 'الإيرادات السنوية'), 'AED 120M'), CaseDatum(Bi('Industry Avg Inventory Turnover', 'متوسط معدل دوران المخزون في القطاع'), '6.0x'), CaseDatum(Bi('Industry Avg Collection Period', 'متوسط فترة التحصيل في القطاع'), '45 days')], question: Bi('Which activity metric reveals the primary cause of the liquidity squeeze?', 'أي مقياس نشاط يكشف السبب الرئيسي لضائقة السيولة؟'), options: [
                CaseOption(Bi('Inventory turnover is extremely low (2.0x) - the municipality is holding 6 months of maintenance supplies instead of the industry standard 2 months', 'معدل دوران المخزون منخفض للغاية (2.0x) - تحتفظ البلدية بلوازم صيانة تكفي 6 أشهر بدلاً من المعيار القطاعي البالغ شهرين'), isCorrect: true, feedback: Bi('Correct! Inventory Turnover = 30M / 15M = 2.0x. Days Inventory Outstanding = 365 / 2.0 = 183 days (6 months). The industry standard is 6.0x turnover (60 days). Overstocking is tying up AED 15M that could be used to pay vendors.', 'صحيح! معدل دوران المخزون = 30M / 15M = 2.0x. عدد أيام بقاء المخزون = 365 / 2.0 = 183 يوماً (6 أشهر). المعيار القطاعي هو معدل دوران 6.0x (60 يوماً). التخزين الزائد يحتجز AED 15M كان يمكن استخدامها لسداد مستحقات الموردين.')),
                CaseOption(Bi('Receivables collection is the problem - the municipality is not collecting fees fast enough', 'تحصيل الذمم المدينة هو المشكلة - لا تحصّل البلدية الرسوم بالسرعة الكافية'), feedback: Bi('Days Sales Outstanding = (10M / 120M) × 365 = 30 days. This is well below the 45-day benchmark, so receivables collection is actually strong.', 'عدد أيام التحصيل = (10M / 120M) × 365 = 30 يوماً. هذا أقل بكثير من المعيار البالغ 45 يوماً، لذا فإن تحصيل الذمم المدينة قوي في الواقع.')),
                CaseOption(Bi('Both inventory and receivables are problematic and need immediate action', 'كل من المخزون والذمم المدينة يمثلان مشكلة ويحتاجان إلى إجراء فوري'), feedback: Bi('Receivables are performing above benchmark (30 days vs. 45 days). The problem is concentrated in inventory management, not receivables.', 'أداء الذمم المدينة أفضل من المعيار (30 يوماً مقابل 45 يوماً). المشكلة متركزة في إدارة المخزون، وليس في الذمم المدينة.')),
            ]),
            CaseStep(id: 'step3', type: CaseStepType.recommendation, title: Bi('Develop Working Capital Strategy', 'وضع استراتيجية رأس المال العامل'), description: Bi('You have diagnosed the issue: excess inventory is draining liquidity. The operations director argues that high inventory is necessary to avoid service disruptions. How do you respond?', 'لقد شخّصت المشكلة: المخزون الزائد يستنزف السيولة. يجادل مدير العمليات بأن ارتفاع المخزون ضروري لتجنب انقطاع الخدمات. كيف ترد؟'), context: Bi('The municipality purchases maintenance supplies in bulk to get volume discounts. However, storage costs and opportunity costs of tied-up capital have not been factored into the purchasing policy.', 'تشتري البلدية لوازم الصيانة بالجملة للحصول على خصومات الكميات. غير أن تكاليف التخزين وتكاليف الفرصة البديلة لرأس المال المحتجز لم تؤخذ في الحسبان ضمن سياسة الشراء.'), question: Bi('What is the best recommendation to improve liquidity without compromising service delivery?', 'ما هي أفضل توصية لتحسين السيولة دون المساس بتقديم الخدمات؟'), options: [
                CaseOption(Bi('Liquidate 50% of inventory immediately and use the cash to pay overdue vendors', 'تصفية 50% من المخزون فوراً واستخدام النقد لسداد مستحقات الموردين المتأخرة'), feedback: Bi('Selling AED 7.5M of maintenance supplies at a discount creates its own losses and may leave the municipality understocked. A controlled drawdown paired with a new purchasing policy is more sustainable.', 'بيع لوازم صيانة بقيمة AED 7.5M بخصم يولّد خسائر بذاته وقد يترك البلدية ناقصة المخزون. إن التخفيض المنضبط المقترن بسياسة شراء جديدة أكثر استدامة.'), consequence: Bi('Fire-sale prices depress realized value; essential supplies may be undersupplied.', 'أسعار البيع الاضطراري تخفض القيمة المحققة؛ وقد تصبح اللوازم الأساسية غير متوفرة بالقدر الكافي.')),
                CaseOption(Bi('Implement just-in-time (JIT) procurement to reduce inventory holding to 2-month benchmark, freeing up AED 10M in working capital', 'تطبيق نظام الشراء في الوقت المناسب (JIT) لتقليص المخزون المحتفظ به إلى المعيار البالغ شهرين، مما يحرر AED 10M من رأس المال العامل'), isCorrect: true, feedback: Bi('Correct! Reducing inventory from 6 months to 2 months (from AED 15M to AED 5M) releases AED 10M. JIT procurement maintains service levels while optimizing cash flow. The AED 10M can immediately pay down the AED 12M overdue payables.', 'صحيح! تقليص المخزون من 6 أشهر إلى شهرين (من AED 15M إلى AED 5M) يحرر AED 10M. يحافظ نظام الشراء في الوقت المناسب على مستويات الخدمة مع تحسين التدفق النقدي. ويمكن استخدام AED 10M فوراً لسداد الذمم الدائنة المتأخرة البالغة AED 12M.'), consequence: Bi('Liquidity improves significantly; vendor relationships are restored as payables are cleared.', 'تتحسن السيولة بشكل كبير؛ وتُستعاد العلاقات مع الموردين مع تسوية الذمم الدائنة.')),
                CaseOption(Bi('Negotiate extended payment terms with vendors to buy time', 'التفاوض على تمديد شروط السداد مع الموردين لكسب الوقت'), feedback: Bi('Vendors are already frustrated with AED 12M in overdue invoices. Asking for longer payment terms without fixing the underlying inventory problem will damage credibility and may result in supply cutoffs.', 'الموردون مستاؤون بالفعل من فواتير متأخرة بقيمة AED 12M. إن طلب شروط سداد أطول دون معالجة مشكلة المخزون الأساسية سيضر بالمصداقية وقد يؤدي إلى قطع الإمدادات.'), consequence: Bi('Vendor relationships deteriorate further; suppliers may demand cash on delivery or stop service.', 'تتدهور العلاقات مع الموردين أكثر؛ وقد يطالب الموردون بالدفع نقداً عند التسليم أو يوقفون الخدمة.')),
            ]),
            CaseStep(id: 'step4', type: CaseStepType.decision, title: Bi('Monitor Implementation Progress', 'متابعة تقدم التنفيذ'), description: Bi('Three months after implementing JIT procurement, the CFO asks you to verify that liquidity has improved as projected. What metric should you track to confirm success?', 'بعد ثلاثة أشهر من تطبيق نظام الشراء في الوقت المناسب، يطلب منك المدير المالي التحقق من تحسن السيولة وفق التوقعات. ما المقياس الذي ينبغي أن تتابعه لتأكيد النجاح؟'), question: Bi('Which ratio best validates that the working capital strategy is succeeding?', 'أي نسبة تؤكد على أفضل نحو أن استراتيجية رأس المال العامل تحقق نجاحاً؟'), options: [
                CaseOption(Bi('Quick Ratio - should increase from 0.45 to above 0.70 as inventory is reduced and cash freed up', 'النسبة السريعة - ينبغي أن ترتفع من 0.45 إلى ما فوق 0.70 مع تقليص المخزون وتحرير النقد'), isCorrect: true, feedback: Bi('Correct! Quick Ratio isolates the most liquid assets. As inventory falls by AED 10M and that cash pays down AED 10M in current liabilities, the Quick Ratio improves: (18M + 10M) / (40M - 10M) = 28M / 30M = 0.93. This is a dramatic improvement from 0.45.', 'صحيح! تعزل النسبة السريعة الأصول الأكثر سيولة. مع انخفاض المخزون بمقدار AED 10M واستخدام ذلك النقد لسداد AED 10M من الالتزامات المتداولة، تتحسن النسبة السريعة: (18M + 10M) / (40M - 10M) = 28M / 30M = 0.93. وهذا تحسن كبير مقارنة بـ 0.45.')),
                CaseOption(Bi('Debt-to-Equity Ratio - to confirm that overall leverage is improving', 'نسبة الدين إلى حقوق الملكية - لتأكيد تحسن الرافعة المالية الإجمالية'), feedback: Bi('Debt-to-Equity is a solvency ratio, not a liquidity ratio. The municipality\'s problem was liquidity (short-term cash flow), not solvency (long-term capital structure).', 'نسبة الدين إلى حقوق الملكية هي نسبة ملاءة، وليست نسبة سيولة. كانت مشكلة البلدية هي السيولة (التدفق النقدي قصير الأجل)، وليست الملاءة (هيكل رأس المال طويل الأجل).')),
                CaseOption(Bi('Return on Assets - to measure operational efficiency gains', 'العائد على الأصول - لقياس المكاسب في الكفاءة التشغيلية'), feedback: Bi('ROA is a profitability metric. While reducing excess inventory may improve ROA slightly, the primary goal of the intervention was to improve liquidity, not profitability.', 'العائد على الأصول (ROA) مقياس للربحية. ومع أن تقليص المخزون الزائد قد يحسّن العائد على الأصول قليلاً، إلا أن الهدف الأساسي من التدخل كان تحسين السيولة، وليس الربحية.')),
            ]),
            CaseStep(id: 'step5', type: CaseStepType.stakeholder, title: Bi('Present Findings to Council', 'عرض النتائج على المجلس'), description: Bi('The Municipal Council has asked for a briefing on the liquidity recovery. How should you frame the results to demonstrate the value of the financial analysis?', 'طلب المجلس البلدي إحاطة حول تعافي السيولة. كيف ينبغي أن تصوغ النتائج لإبراز قيمة التحليل المالي؟'), question: Bi('What is the most effective way to communicate the impact of the liquidity improvement?', 'ما هي الطريقة الأكثر فعالية لتوصيل أثر تحسن السيولة؟'), options: [
                CaseOption(Bi('Focus on technical metrics: "Quick Ratio improved from 0.45 to 0.93"', 'التركيز على المقاييس الفنية: النسبة السريعة تحسنت من 0.45 إلى 0.93'), feedback: Bi('Council members may not understand ratio terminology. Leading with technical jargon risks losing the audience.', 'قد لا يفهم أعضاء المجلس مصطلحات النسب المالية. إن الاستهلال بالمصطلحات الفنية يهدد بفقدان اهتمام الجمهور.')),
                CaseOption(Bi('Lead with business impact: "We freed AED 10M in working capital, cleared vendor backlogs, and restored payment reliability - all without disrupting services"', 'الاستهلال بالأثر على الأعمال: حررنا AED 10M من رأس المال العامل، وسوّينا متأخرات الموردين، واستعدنا موثوقية السداد - كل ذلك دون تعطيل الخدمات'), isCorrect: true, feedback: Bi('Correct! Start with outcomes that stakeholders care about (cash freed, vendors paid, service continuity), then support with the technical ratios as evidence. This approach connects financial analysis to real-world results.', 'صحيح! ابدأ بالنتائج التي تهم أصحاب المصلحة (النقد المحرر، الموردون المسددة مستحقاتهم، استمرارية الخدمة)، ثم ادعمها بالنسب الفنية كدليل. يربط هذا النهج التحليل المالي بالنتائج الواقعية.')),
                CaseOption(Bi('Emphasize that the CFO\'s original concerns were overstated', 'التأكيد على أن مخاوف المدير المالي الأصلية كانت مبالغاً فيها'), feedback: Bi('The CFO was correct to flag the problem. Framing the success as proving the CFO wrong is counterproductive and damages collaboration.', 'كان المدير المالي محقاً في التنبيه إلى المشكلة. إن تصوير النجاح على أنه إثبات لخطأ المدير المالي أمر يأتي بنتائج عكسية ويضر بالتعاون.')),
            ]),
          ]),
        CaseScenario(id: 'scenario2', title: Bi('Multi-Year Trend Analysis', 'تحليل الاتجاهات متعددة السنوات'), role: Bi('Senior Financial Analyst, Gulf Utilities Corporation', 'محلل مالي أول، شركة الخليج للمرافق'), overview: Bi('Gulf Utilities Corporation, a government-owned power provider, has shown declining profitability over the past three years. The board is concerned but unsure whether this is a temporary dip or a structural decline. You must perform horizontal and vertical analysis to identify trends and recommend corrective action.', 'أظهرت شركة الخليج للمرافق، وهي مزود طاقة مملوك للدولة، تراجعاً في الربحية على مدى السنوات الثلاث الماضية. يساور مجلس الإدارة القلق لكنه غير متأكد مما إذا كان هذا هبوطاً مؤقتاً أم تراجعاً هيكلياً. عليك إجراء تحليل أفقي ورأسي لتحديد الاتجاهات والتوصية بإجراء تصحيحي.'), finalSummary: Bi('You successfully used horizontal and vertical analysis to identify a structural profitability decline, traced the root cause to fuel cost inflation, and recommended a balanced strategy of tariff recovery and renewable energy investment. This scenario demonstrates how trend analysis converts multi-year financial data into strategic insights.', 'لقد استخدمت بنجاح التحليل الأفقي والرأسي لتحديد تراجع هيكلي في الربحية، وتتبعت السبب الجذري وصولاً إلى تضخم تكاليف الوقود، وأوصيت باستراتيجية متوازنة تجمع بين استرداد التعرفة والاستثمار في الطاقة المتجددة. يبرهن هذا السيناريو على كيفية تحويل تحليل الاتجاهات للبيانات المالية متعددة السنوات إلى رؤى استراتيجية.'), steps: [
            CaseStep(id: 'step1', type: CaseStepType.analysis, title: Bi('Perform Horizontal Analysis', 'إجراء التحليل الأفقي'), description: Bi('Examine the three-year income statement and calculate percentage changes to identify trends.', 'افحص قائمة الدخل لثلاث سنوات واحسب نسب التغير المئوية لتحديد الاتجاهات.'), data: [CaseDatum(Bi('Revenue (Year 1)', 'الإيرادات (السنة 1)'), 'AED 500M'), CaseDatum(Bi('Revenue (Year 2)', 'الإيرادات (السنة 2)'), 'AED 520M'), CaseDatum(Bi('Revenue (Year 3)', 'الإيرادات (السنة 3)'), 'AED 545M'), CaseDatum(Bi('Operating Expenses (Year 1)', 'المصروفات التشغيلية (السنة 1)'), 'AED 350M'), CaseDatum(Bi('Operating Expenses (Year 2)', 'المصروفات التشغيلية (السنة 2)'), 'AED 380M'), CaseDatum(Bi('Operating Expenses (Year 3)', 'المصروفات التشغيلية (السنة 3)'), 'AED 420M'), CaseDatum(Bi('Net Income (Year 1)', 'صافي الدخل (السنة 1)'), 'AED 100M'), CaseDatum(Bi('Net Income (Year 2)', 'صافي الدخل (السنة 2)'), 'AED 90M'), CaseDatum(Bi('Net Income (Year 3)', 'صافي الدخل (السنة 3)'), 'AED 75M')], question: Bi('What does horizontal analysis reveal about the company\'s performance trend?', 'ماذا يكشف التحليل الأفقي عن اتجاه أداء الشركة؟'), options: [
                CaseOption(Bi('Revenue is growing steadily (+9% over 3 years), but operating expenses are growing faster (+20%), eroding margins', 'الإيرادات تنمو باطراد (+9% خلال 3 سنوات)، لكن المصروفات التشغيلية تنمو بوتيرة أسرع (+20%)، مما يؤدي إلى تآكل الهوامش'), isCorrect: true, feedback: Bi('Correct! Revenue grew from AED 500M to AED 545M (+9%). Operating expenses grew from AED 350M to AED 420M (+20%). The expense growth rate is more than double the revenue growth rate, causing net income to fall from AED 100M to AED 75M (-25%).', 'صحيح! نمت الإيرادات من AED 500M إلى AED 545M (+9%). ونمت المصروفات التشغيلية من AED 350M إلى AED 420M (+20%). إن معدل نمو المصروفات أكثر من ضعف معدل نمو الإيرادات، مما أدى إلى انخفاض صافي الدخل من AED 100M إلى AED 75M (-25%).')),
                CaseOption(Bi('Both revenue and expenses are declining - the company is shrinking', 'كل من الإيرادات والمصروفات في انخفاض - الشركة تتقلص'), feedback: Bi('Revenue is actually growing each year (500M → 520M → 545M). The problem is not shrinking revenue, but accelerating expenses.', 'الإيرادات في الواقع تنمو كل عام (500M ← 520M ← 545M). المشكلة ليست في تقلص الإيرادات، بل في تسارع المصروفات.')),
                CaseOption(Bi('Performance is stable - all metrics are within normal fluctuations', 'الأداء مستقر - جميع المقاييس ضمن التقلبات الطبيعية'), feedback: Bi('Net income has declined 25% over three years. This is a significant erosion, not a normal fluctuation.', 'انخفض صافي الدخل بنسبة 25% خلال ثلاث سنوات. هذا تآكل كبير، وليس تقلباً طبيعياً.')),
            ]),
            CaseStep(id: 'step2', type: CaseStepType.analysis, title: Bi('Perform Vertical Analysis', 'إجراء التحليل الرأسي'), description: Bi('Convert the income statement to common-size format to see how the expense structure is changing as a percentage of revenue.', 'حوّل قائمة الدخل إلى صيغة الحجم الموحد لرؤية كيف يتغير هيكل المصروفات كنسبة مئوية من الإيرادات.'), data: [CaseDatum(Bi('Year 1: Operating Expenses / Revenue', 'السنة 1: المصروفات التشغيلية / الإيرادات'), '350M / 500M = 70%'), CaseDatum(Bi('Year 2: Operating Expenses / Revenue', 'السنة 2: المصروفات التشغيلية / الإيرادات'), '380M / 520M = 73%'), CaseDatum(Bi('Year 3: Operating Expenses / Revenue', 'السنة 3: المصروفات التشغيلية / الإيرادات'), '420M / 545M = 77%'), CaseDatum(Bi('Year 1: Net Margin', 'السنة 1: هامش صافي الربح'), '100M / 500M = 20%'), CaseDatum(Bi('Year 2: Net Margin', 'السنة 2: هامش صافي الربح'), '90M / 520M = 17%'), CaseDatum(Bi('Year 3: Net Margin', 'السنة 3: هامش صافي الربح'), '75M / 545M = 14%')], question: Bi('What does vertical analysis reveal about the nature of the profitability decline?', 'ماذا يكشف التحليل الرأسي عن طبيعة تراجع الربحية؟'), options: [
                CaseOption(Bi('Operating expenses as a percentage of revenue are rising (70% → 73% → 77%), indicating structural cost inflation that is outpacing pricing power', 'المصروفات التشغيلية كنسبة مئوية من الإيرادات في ارتفاع (70% ← 73% ← 77%)، مما يشير إلى تضخم هيكلي في التكاليف يفوق القدرة على التسعير'), isCorrect: true, feedback: Bi('Correct! Common-size analysis shows the expense ratio is climbing steadily. Net margin has compressed from 20% to 14% over three years. This is not random volatility - it is a systematic trend of cost growth outstripping revenue growth.', 'صحيح! يُظهر تحليل الحجم الموحد أن نسبة المصروفات ترتفع باطراد. وقد انكمش هامش صافي الربح من 20% إلى 14% خلال ثلاث سنوات. هذا ليس تقلباً عشوائياً - بل هو اتجاه منهجي لنمو التكاليف يتجاوز نمو الإيرادات.')),
                CaseOption(Bi('The company is investing heavily in growth, which temporarily depresses margins', 'الشركة تستثمر بكثافة في النمو، مما يخفض الهوامش مؤقتاً'), feedback: Bi('There is no indication in the data that expenses are growth-related capital investments. The expense line is labeled "Operating Expenses," which are recurring costs, not investments.', 'لا يوجد في البيانات ما يشير إلى أن المصروفات استثمارات رأسمالية مرتبطة بالنمو. فبند المصروفات مصنّف باعتباره المصروفات التشغيلية، وهي تكاليف متكررة وليست استثمارات.')),
                CaseOption(Bi('Vertical analysis does not add new insight beyond what horizontal analysis already revealed', 'التحليل الرأسي لا يضيف رؤية جديدة تتجاوز ما كشفه التحليل الأفقي بالفعل'), feedback: Bi('Vertical analysis provides a different lens: it shows that every dirham of revenue is retaining less and less margin (20% → 17% → 14%). This relative deterioration is a critical insight.', 'يوفر التحليل الرأسي منظوراً مختلفاً: فهو يُظهر أن كل درهم من الإيرادات يحتفظ بهامش أقل فأقل (20% ← 17% ← 14%). هذا التدهور النسبي رؤية بالغة الأهمية.')),
            ]),
            CaseStep(id: 'step3', type: CaseStepType.analysis, title: Bi('Identify Root Cause', 'تحديد السبب الجذري'), description: Bi('You meet with the operations team to understand what is driving the 20% expense growth. They present a breakdown of cost categories.', 'تجتمع بفريق العمليات لفهم ما يدفع نمو المصروفات بنسبة 20%. ويقدمون لك تفصيلاً لفئات التكاليف.'), context: Bi('Global energy markets have been volatile. Natural gas prices (the utility\'s primary fuel source) have increased by 35% over the same period.', 'اتسمت أسواق الطاقة العالمية بالتقلب. فقد ارتفعت أسعار الغاز الطبيعي (مصدر الوقود الرئيسي للمرفق) بنسبة 35% خلال الفترة نفسها.'), data: [CaseDatum(Bi('Fuel Costs (Year 1 to Year 3)', 'تكاليف الوقود (السنة 1 إلى السنة 3)'), 'AED 200M → AED 280M (+40%)'), CaseDatum(Bi('Labor Costs (Year 1 to Year 3)', 'تكاليف العمالة (السنة 1 إلى السنة 3)'), 'AED 100M → AED 95M (-5%)'), CaseDatum(Bi('Maintenance (Year 1 to Year 3)', 'الصيانة (السنة 1 إلى السنة 3)'), 'AED 50M → AED 45M (-10%)')], question: Bi('What is the primary driver of the expense growth?', 'ما المحرك الرئيسي لنمو المصروفات؟'), options: [
                CaseOption(Bi('Fuel costs have surged 40% due to global energy inflation - this accounts for the entire AED 70M expense increase', 'ارتفعت تكاليف الوقود بنسبة 40% بسبب تضخم الطاقة العالمي - وهذا يفسر كامل الزيادة في المصروفات البالغة AED 70M'), isCorrect: true, feedback: Bi('Correct! Fuel costs increased AED 80M (200M → 280M). Labor and maintenance actually declined by a combined AED 10M. The net increase of AED 70M in total operating expenses (350M → 420M) is entirely attributable to fuel inflation.', 'صحيح! ارتفعت تكاليف الوقود بمقدار AED 80M (200M ← 280M). وانخفضت العمالة والصيانة في الواقع بما مجموعه AED 10M. إن الزيادة الصافية البالغة AED 70M في إجمالي المصروفات التشغيلية (350M ← 420M) تُعزى بالكامل إلى تضخم أسعار الوقود.')),
                CaseOption(Bi('Labor inefficiency is the problem - headcount is bloated', 'عدم كفاءة العمالة هو المشكلة - عدد الموظفين متضخم'), feedback: Bi('Labor costs have actually declined 5%. The data does not support a labor inefficiency hypothesis.', 'انخفضت تكاليف العمالة في الواقع بنسبة 5%. لا تدعم البيانات فرضية عدم كفاءة العمالة.')),
                CaseOption(Bi('All cost categories are rising - there is no single root cause', 'جميع فئات التكاليف في ارتفاع - لا يوجد سبب جذري واحد'), feedback: Bi('Two of the three categories (labor and maintenance) are declining. The problem is concentrated in fuel costs, which have exploded by 40%.', 'فئتان من الفئات الثلاث (العمالة والصيانة) في انخفاض. المشكلة متركزة في تكاليف الوقود التي انفجرت بنسبة 40%.')),
            ]),
            CaseStep(id: 'step4', type: CaseStepType.recommendation, title: Bi('Evaluate Strategic Options', 'تقييم الخيارات الاستراتيجية'), description: Bi('With fuel inflation identified as the root cause, the board is debating three strategic responses. Which recommendation aligns best with the financial analysis?', 'بعد تحديد تضخم أسعار الوقود بوصفه السبب الجذري، يناقش مجلس الإدارة ثلاثة ردود استراتيجية. أي توصية تتوافق على أفضل نحو مع التحليل المالي؟'), question: Bi('What is the most appropriate strategic response to fuel cost inflation?', 'ما هو الرد الاستراتيجي الأنسب لتضخم تكاليف الوقود؟'), options: [
                CaseOption(Bi('Cut labor and maintenance costs by 20% to offset fuel inflation', 'خفض تكاليف العمالة والصيانة بنسبة 20% لتعويض تضخم أسعار الوقود'), feedback: Bi('Labor and maintenance have already been reduced. Further cuts risk operational safety and service quality. Cutting a combined AED 28M (20% of AED 140M) would not offset the AED 80M fuel increase.', 'تم بالفعل خفض العمالة والصيانة. والمزيد من التخفيضات يهدد السلامة التشغيلية وجودة الخدمة. إن خفض ما مجموعه AED 28M (20% من AED 140M) لن يعوض الزيادة في الوقود البالغة AED 80M.'), consequence: Bi('Service reliability deteriorates; deferred maintenance leads to equipment failures.', 'تتدهور موثوقية الخدمة؛ وتؤدي الصيانة المؤجلة إلى أعطال المعدات.')),
                CaseOption(Bi('Absorb the cost increases and accept lower margins as the new normal', 'استيعاب الزيادات في التكاليف وقبول هوامش أدنى باعتبارها الوضع الطبيعي الجديد'), feedback: Bi('If fuel prices continue to rise, margins will continue to compress. Passive acceptance is not a strategy - it is a slow path to unsustainability.', 'إذا استمرت أسعار الوقود في الارتفاع، فستستمر الهوامش في الانكماش. القبول السلبي ليس استراتيجية - بل هو مسار بطيء نحو عدم الاستدامة.'), consequence: Bi('Margins continue to erode; eventual subsidy requests or service cuts become unavoidable.', 'تستمر الهوامش في التآكل؛ وتصبح طلبات الدعم أو تخفيضات الخدمة في نهاية المطاف أمراً لا مفر منه.')),
                CaseOption(Bi('Implement inflation-adjusted tariff increases and accelerate renewable energy transition to reduce fuel dependency', 'تطبيق زيادات في التعرفة معدّلة حسب التضخم وتسريع التحول إلى الطاقة المتجددة لتقليل الاعتماد على الوقود'), isCorrect: true, feedback: Bi('Correct! Tariff adjustments recover fuel cost pass-throughs (common in regulated utilities). Investing in solar/wind generation reduces long-term exposure to volatile fossil fuel markets. This addresses both the immediate margin squeeze and the structural risk.', 'صحيح! تعديلات التعرفة تسترد تمرير تكاليف الوقود (وهو أمر شائع في المرافق الخاضعة للتنظيم). والاستثمار في توليد الطاقة الشمسية وطاقة الرياح يقلل التعرض طويل الأجل لأسواق الوقود الأحفوري المتقلبة. وهذا يعالج ضائقة الهامش الفورية والمخاطر الهيكلية على حد سواء.'), consequence: Bi('Revenue grows in line with costs; renewable investments insulate against future fuel shocks.', 'تنمو الإيرادات بما يتماشى مع التكاليف؛ وتحمي استثمارات الطاقة المتجددة من صدمات الوقود المستقبلية.')),
            ]),
            CaseStep(id: 'step5', type: CaseStepType.decision, title: Bi('Monitor Recovery Metrics', 'متابعة مقاييس التعافي'), description: Bi('One year after implementing tariff adjustments and beginning renewable investment, you are asked to assess progress. Which metric best validates the strategy\'s success?', 'بعد عام من تطبيق تعديلات التعرفة وبدء الاستثمار في الطاقة المتجددة، يُطلب منك تقييم التقدم. أي مقياس يؤكد على أفضل نحو نجاح الاستراتيجية؟'), question: Bi('What metric should you track to confirm the turnaround is working?', 'ما المقياس الذي ينبغي أن تتابعه لتأكيد نجاح خطة التصحيح؟'), options: [
                CaseOption(Bi('Return to Year 1 net margin levels (20%) through tariff recovery and stabilized fuel mix', 'العودة إلى مستويات هامش صافي الربح في السنة 1 (20%) من خلال استرداد التعرفة واستقرار مزيج الوقود'), isCorrect: true, feedback: Bi('Correct! The goal is to restore profitability to sustainable levels. If tariffs properly recover fuel costs and renewable capacity begins to offset gas exposure, net margin should stabilize near the original 20% target.', 'صحيح! الهدف هو استعادة الربحية إلى مستويات مستدامة. إذا استردت التعرفة تكاليف الوقود على نحو سليم وبدأت قدرة الطاقة المتجددة في تعويض التعرض للغاز، فينبغي أن يستقر هامش صافي الربح قرب الهدف الأصلي البالغ 20%.')),
                CaseOption(Bi('Absolute reduction in fuel costs below Year 1 levels', 'خفض مطلق في تكاليف الوقود دون مستويات السنة 1'), feedback: Bi('Renewable investments take years to materially reduce fuel consumption. The immediate goal is margin recovery through tariff adjustments, not an absolute fuel cost reduction.', 'تستغرق استثمارات الطاقة المتجددة سنوات لخفض استهلاك الوقود بشكل ملموس. الهدف الفوري هو استعادة الهامش من خلال تعديلات التعرفة، وليس خفضاً مطلقاً لتكاليف الوقود.')),
                CaseOption(Bi('Revenue growth acceleration to 15% per year', 'تسريع نمو الإيرادات إلى 15% سنوياً'), feedback: Bi('Revenue growth is not the problem - revenue has been growing steadily at 4-5% per year. The issue was margin compression from cost inflation. Chasing aggressive revenue growth is not the solution.', 'نمو الإيرادات ليس المشكلة - فالإيرادات تنمو باطراد بمعدل 4-5% سنوياً. المشكلة كانت انكماش الهامش الناتج عن تضخم التكاليف. إن السعي وراء نمو إيرادات متسارع ليس هو الحل.')),
            ]),
          ]),
        CaseScenario(id: 'scenario3', title: Bi('DuPont ROE Decomposition', 'تحليل ديبونت لتفكيك العائد على حقوق الملكية'), role: Bi('Strategic Finance Manager, National Housing Bank', 'مدير المالية الاستراتيجية، بنك الإسكان الوطني'), overview: Bi('National Housing Bank, a government-owned financial institution, has delivered a 12% Return on Equity (ROE) for the past five years. The new CEO wants to improve ROE to 15% to match private-sector competitors. You must use DuPont analysis to identify which component of ROE should be the focus of improvement efforts.', 'حقق بنك الإسكان الوطني، وهو مؤسسة مالية مملوكة للدولة، عائداً على حقوق الملكية (ROE) بنسبة 12% خلال السنوات الخمس الماضية. ويرغب الرئيس التنفيذي الجديد في تحسين العائد على حقوق الملكية إلى 15% لمجاراة المنافسين في القطاع الخاص. عليك استخدام تحليل ديبونت لتحديد أي مكوّن من مكونات العائد على حقوق الملكية ينبغي أن يكون محور جهود التحسين.'), finalSummary: Bi('You successfully used DuPont analysis to decompose ROE into profit margin, asset turnover, and leverage, benchmarked against competitors to identify asset turnover as the key gap, traced the gap to non-performing loans, and built a data-driven case for NPL recovery over risky leverage increases. This scenario demonstrates how DuPont analysis transforms a single ROE number into actionable strategic insights.', 'لقد استخدمت بنجاح تحليل ديبونت لتفكيك العائد على حقوق الملكية إلى هامش الربح ومعدل دوران الأصول والرافعة المالية، وأجريت مقارنة مرجعية مع المنافسين لتحديد معدل دوران الأصول باعتباره الفجوة الرئيسية، وتتبعت الفجوة وصولاً إلى القروض المتعثرة، وبنيت حجة مستندة إلى البيانات لصالح تحصيل القروض المتعثرة بدلاً من زيادات الرافعة المالية المحفوفة بالمخاطر. يبرهن هذا السيناريو على كيفية تحويل تحليل ديبونت لرقم واحد للعائد على حقوق الملكية إلى رؤى استراتيجية قابلة للتنفيذ.'), steps: [
            CaseStep(id: 'step1', type: CaseStepType.analysis, title: Bi('Decompose Current ROE', 'تفكيك العائد على حقوق الملكية الحالي'), description: Bi('Apply the DuPont formula to break down the bank\'s 12% ROE into its three components: Profit Margin, Asset Turnover, and Equity Multiplier.', 'طبّق معادلة ديبونت لتفكيك العائد على حقوق الملكية البالغ 12% للبنك إلى مكوناته الثلاثة: هامش الربح، ومعدل دوران الأصول، ومضاعف حقوق الملكية.'), context: Bi('DuPont Formula: ROE = (Net Income / Revenue) × (Revenue / Assets) × (Assets / Equity)', 'معادلة ديبونت: ROE = (صافي الدخل / الإيرادات) × (الإيرادات / الأصول) × (الأصول / حقوق الملكية)'), data: [CaseDatum(Bi('Net Income', 'صافي الدخل'), 'AED 240M'), CaseDatum(Bi('Revenue (Interest Income)', 'الإيرادات (إيرادات الفوائد)'), 'AED 800M'), CaseDatum(Bi('Total Assets', 'إجمالي الأصول'), 'AED 10,000M'), CaseDatum(Bi('Total Equity', 'إجمالي حقوق الملكية'), 'AED 2,000M'), CaseDatum(Bi('ROE', 'العائد على حقوق الملكية (ROE)'), '240M / 2,000M = 12%')], question: Bi('Calculate the three DuPont components. What do the results reveal?', 'احسب مكونات ديبونت الثلاثة. ماذا تكشف النتائج؟'), options: [
                CaseOption(Bi('Profit Margin = 30%, Asset Turnover = 0.08, Equity Multiplier = 5.0', 'هامش الربح = 30%، معدل دوران الأصول = 0.08، مضاعف حقوق الملكية = 5.0'), isCorrect: true, feedback: Bi('Correct! Profit Margin = 240M / 800M = 30%. Asset Turnover = 800M / 10,000M = 0.08. Equity Multiplier = 10,000M / 2,000M = 5.0. Multiply: 0.30 × 0.08 × 5.0 = 0.12 (12% ROE).', 'صحيح! هامش الربح = 240M / 800M = 30%. معدل دوران الأصول = 800M / 10,000M = 0.08. مضاعف حقوق الملكية = 10,000M / 2,000M = 5.0. حاصل الضرب: 0.30 × 0.08 × 5.0 = 0.12 (عائد على حقوق الملكية بنسبة 12%).')),
                CaseOption(Bi('Profit Margin = 12%, Asset Turnover = 1.0, Equity Multiplier = 1.0', 'هامش الربح = 12%، معدل دوران الأصول = 1.0، مضاعف حقوق الملكية = 1.0'), feedback: Bi('These values would imply ROE = 0.12 × 1.0 × 1.0 = 12%, but they do not match the underlying balance sheet and income statement data.', 'هذه القيم تعني ضمناً أن العائد على حقوق الملكية = 0.12 × 1.0 × 1.0 = 12%، لكنها لا تتطابق مع بيانات قائمة المركز المالي وقائمة الدخل الأساسية.')),
                CaseOption(Bi('DuPont analysis cannot be applied to a bank because banks have unique business models', 'لا يمكن تطبيق تحليل ديبونت على بنك لأن البنوك لها نماذج أعمال فريدة'), feedback: Bi('DuPont analysis applies to all companies, including banks. The components (margin, turnover, leverage) are universally applicable, though banks typically have lower turnover and higher leverage than industrials.', 'ينطبق تحليل ديبونت على جميع الشركات، بما في ذلك البنوك. فمكوناته (الهامش، ومعدل الدوران، والرافعة المالية) قابلة للتطبيق عالمياً، وإن كانت البنوك عادةً ما يكون معدل دورانها أدنى ورافعتها المالية أعلى من الشركات الصناعية.')),
            ]),
            CaseStep(id: 'step2', type: CaseStepType.analysis, title: Bi('Benchmark Against Competitors', 'المقارنة المرجعية مع المنافسين'), description: Bi('You compare National Housing Bank\'s DuPont components to the average of three private-sector competitors.', 'تقارن مكونات ديبونت لبنك الإسكان الوطني بمتوسط ثلاثة منافسين من القطاع الخاص.'), data: [CaseDatum(Bi('NHB Profit Margin', 'هامش ربح بنك الإسكان الوطني'), '30%'), CaseDatum(Bi('Competitor Avg Profit Margin', 'متوسط هامش ربح المنافسين'), '28%'), CaseDatum(Bi('NHB Asset Turnover', 'معدل دوران أصول بنك الإسكان الوطني'), '0.08'), CaseDatum(Bi('Competitor Avg Asset Turnover', 'متوسط معدل دوران أصول المنافسين'), '0.12'), CaseDatum(Bi('NHB Equity Multiplier', 'مضاعف حقوق ملكية بنك الإسكان الوطني'), '5.0'), CaseDatum(Bi('Competitor Avg Equity Multiplier', 'متوسط مضاعف حقوق ملكية المنافسين'), '4.5')], question: Bi('Which DuPont component represents the biggest competitive gap?', 'أي مكوّن من مكونات ديبونت يمثل أكبر فجوة تنافسية؟'), options: [
                CaseOption(Bi('Asset Turnover - NHB generates AED 0.08 of revenue per dirham of assets vs. AED 0.12 for competitors (33% gap)', 'معدل دوران الأصول - يحقق بنك الإسكان الوطني AED 0.08 من الإيرادات لكل درهم من الأصول مقابل AED 0.12 للمنافسين (فجوة 33%)'), isCorrect: true, feedback: Bi('Correct! NHB\'s profit margin (30%) actually exceeds competitors (28%). The equity multiplier is slightly higher (5.0 vs. 4.5), which is a minor advantage. The major gap is asset turnover: 0.08 vs. 0.12. NHB\'s assets are underutilized.', 'صحيح! هامش ربح بنك الإسكان الوطني (30%) يتجاوز في الواقع المنافسين (28%). ومضاعف حقوق الملكية أعلى قليلاً (5.0 مقابل 4.5)، وهي ميزة طفيفة. الفجوة الكبرى هي في معدل دوران الأصول: 0.08 مقابل 0.12. فأصول البنك مستغلة بأقل من طاقتها.')),
                CaseOption(Bi('Profit Margin - NHB needs to improve profitability per unit of revenue', 'هامش الربح - يحتاج بنك الإسكان الوطني إلى تحسين الربحية لكل وحدة من الإيرادات'), feedback: Bi('NHB\'s profit margin (30%) is already higher than the competitor average (28%). Margin is a relative strength, not a gap.', 'هامش ربح بنك الإسكان الوطني (30%) أعلى بالفعل من متوسط المنافسين (28%). الهامش نقطة قوة نسبية، وليس فجوة.')),
                CaseOption(Bi('Equity Multiplier - NHB should increase leverage to match competitors', 'مضاعف حقوق الملكية - ينبغي أن يزيد بنك الإسكان الوطني الرافعة المالية لمجاراة المنافسين'), feedback: Bi('NHB\'s equity multiplier (5.0) is already higher than competitors (4.5). Increasing leverage further would expose the bank to greater financial risk without addressing the root inefficiency.', 'مضاعف حقوق ملكية بنك الإسكان الوطني (5.0) أعلى بالفعل من المنافسين (4.5). وزيادة الرافعة المالية أكثر ستعرّض البنك لمخاطر مالية أكبر دون معالجة عدم الكفاءة الجذري.')),
            ]),
            CaseStep(id: 'step3', type: CaseStepType.analysis, title: Bi('Identify Asset Utilization Issue', 'تحديد مشكلة استغلال الأصول'), description: Bi('You drill into the balance sheet to understand why asset turnover is low. The bank\'s lending portfolio shows the following composition.', 'تتعمق في قائمة المركز المالي لفهم سبب انخفاض معدل دوران الأصول. وتُظهر محفظة الإقراض لدى البنك التكوين التالي.'), data: [CaseDatum(Bi('Active Mortgage Loans', 'قروض الرهن العقاري النشطة'), 'AED 7,000M (generating AED 700M interest annually)'), CaseDatum(Bi('Non-Performing Loans (NPL)', 'القروض المتعثرة (NPL)'), 'AED 1,500M (generating AED 0 interest)'), CaseDatum(Bi('Cash & Reserves', 'النقد والاحتياطيات'), 'AED 1,000M (generating AED 50M interest)'), CaseDatum(Bi('Other Assets', 'أصول أخرى'), 'AED 500M (generating AED 50M interest)')], question: Bi('What is the root cause of low asset turnover?', 'ما السبب الجذري لانخفاض معدل دوران الأصول؟'), options: [
                CaseOption(Bi('Non-performing loans (AED 1,500M) are dragging down asset productivity - they represent 15% of assets but generate zero revenue', 'القروض المتعثرة (AED 1,500M) تسحب إنتاجية الأصول إلى الأسفل - فهي تمثل 15% من الأصول لكنها لا تولّد أي إيرادات'), isCorrect: true, feedback: Bi('Correct! AED 1,500M in NPLs sit on the balance sheet inflating assets without contributing to revenue. Removing or recovering NPLs would improve asset turnover. If NPLs were zero, assets would be AED 8,500M and turnover = 800M / 8,500M = 0.094 (still below 0.12, but closer).', 'صحيح! تقبع قروض متعثرة بقيمة AED 1,500M في قائمة المركز المالي تضخّم الأصول دون أن تسهم في الإيرادات. إن إزالة القروض المتعثرة أو تحصيلها سيحسّن معدل دوران الأصول. لو كانت القروض المتعثرة صفراً، لبلغت الأصول AED 8,500M وأصبح معدل الدوران = 800M / 8,500M = 0.094 (لا يزال أقل من 0.12، لكنه أقرب).')),
                CaseOption(Bi('The bank is holding too much cash (AED 1,000M) instead of deploying it into loans', 'يحتفظ البنك بنقد أكثر من اللازم (AED 1,000M) بدلاً من توظيفه في القروض'), feedback: Bi('AED 1,000M in cash is a prudent liquidity buffer (10% of assets). The real problem is AED 1,500M in unproductive NPLs, not cash reserves.', 'مبلغ AED 1,000M من النقد يمثل احتياطي سيولة حصيفاً (10% من الأصول). المشكلة الحقيقية هي AED 1,500M من القروض المتعثرة غير المنتجة، وليست الاحتياطيات النقدية.')),
                CaseOption(Bi('The bank needs to expand its loan portfolio aggressively to grow assets faster', 'يحتاج البنك إلى توسيع محفظة قروضه بقوة لتنمية الأصول بشكل أسرع'), feedback: Bi('The problem is not the size of the loan portfolio, but its quality. Growing assets without fixing the NPL problem would make asset turnover worse, not better.', 'المشكلة ليست في حجم محفظة القروض، بل في جودتها. إن تنمية الأصول دون معالجة مشكلة القروض المتعثرة ستزيد معدل دوران الأصول سوءاً، لا تحسناً.')),
            ]),
            CaseStep(id: 'step4', type: CaseStepType.decision, title: Bi('Develop ROE Improvement Plan', 'وضع خطة تحسين العائد على حقوق الملكية'), description: Bi('You recommend a strategy to reduce NPLs and improve asset turnover. The CEO asks: what impact will this have on the 15% ROE target?', 'توصي باستراتيجية لتقليل القروض المتعثرة وتحسين معدل دوران الأصول. ويسأل الرئيس التنفيذي: ما الأثر الذي سيحدثه ذلك على هدف العائد على حقوق الملكية البالغ 15%؟'), context: Bi('Assume the bank can recover or write off AED 1,000M of NPLs over two years through restructuring and collections. This would reduce total assets to AED 9,000M.', 'افترض أن البنك قادر على تحصيل أو شطب AED 1,000M من القروض المتعثرة على مدى عامين من خلال إعادة الهيكلة والتحصيل. وهذا سيخفض إجمالي الأصول إلى AED 9,000M.'), question: Bi('If NPL reduction improves asset turnover, what ROE can the bank achieve?', 'إذا حسّن تقليص القروض المتعثرة معدل دوران الأصول، فما العائد على حقوق الملكية الذي يمكن أن يحققه البنك؟'), options: [
                CaseOption(Bi('Asset Turnover improves to 0.089 (800M / 9,000M), lifting ROE to 13.3% - not quite 15%, but a meaningful step forward', 'يتحسن معدل دوران الأصول إلى 0.089 (800M / 9,000M)، مما يرفع العائد على حقوق الملكية إلى 13.3% - ليس 15% تماماً، لكنه خطوة مهمة إلى الأمام'), isCorrect: true, feedback: Bi('Correct! New ROE = 0.30 (margin) × 0.089 (turnover) × 5.0 (multiplier) = 13.3%. This closes half the gap from 12% to 15%. The bank would need to also grow revenue or reduce equity slightly to reach 15%, but NPL reduction is the critical first step.', 'صحيح! العائد الجديد على حقوق الملكية = 0.30 (الهامش) × 0.089 (معدل الدوران) × 5.0 (المضاعف) = 13.3%. وهذا يسد نصف الفجوة من 12% إلى 15%. سيحتاج البنك أيضاً إلى تنمية الإيرادات أو خفض حقوق الملكية قليلاً للوصول إلى 15%، لكن تقليص القروض المتعثرة هو الخطوة الأولى الحاسمة.')),
                CaseOption(Bi('ROE jumps immediately to 15% because asset reduction automatically improves ROE', 'يقفز العائد على حقوق الملكية فوراً إلى 15% لأن خفض الأصول يحسّن العائد على حقوق الملكية تلقائياً'), feedback: Bi('Reducing assets improves asset turnover, but the effect must be calculated through the DuPont formula. A simple reduction does not guarantee hitting the 15% target.', 'خفض الأصول يحسّن معدل دوران الأصول، لكن يجب حساب الأثر من خلال معادلة ديبونت. إن مجرد الخفض لا يضمن بلوغ الهدف البالغ 15%.')),
                CaseOption(Bi('ROE declines because writing off NPLs reduces equity', 'ينخفض العائد على حقوق الملكية لأن شطب القروض المتعثرة يقلل حقوق الملكية'), feedback: Bi('NPLs are already fully provisioned in this scenario (the AED 240M net income already reflects NPL provisions). Writing them off removes dead assets and cleans the balance sheet, improving efficiency.', 'القروض المتعثرة مخصص لها بالكامل بالفعل في هذا السيناريو (صافي الدخل البالغ AED 240M يعكس بالفعل مخصصات القروض المتعثرة). وشطبها يزيل الأصول الميتة وينظف قائمة المركز المالي، مما يحسّن الكفاءة.')),
            ]),
            CaseStep(id: 'step5', type: CaseStepType.stakeholder, title: Bi('Present Strategy to the Board', 'عرض الاستراتيجية على مجلس الإدارة'), description: Bi('The board is skeptical that focusing on NPL recovery is the right path to improving ROE. They suggest instead increasing leverage (borrowing more) to boost the equity multiplier. How do you respond?', 'يشكك مجلس الإدارة في أن التركيز على تحصيل القروض المتعثرة هو المسار الصحيح لتحسين العائد على حقوق الملكية. ويقترحون بدلاً من ذلك زيادة الرافعة المالية (المزيد من الاقتراض) لرفع مضاعف حقوق الملكية. كيف ترد؟'), question: Bi('What is the best argument for prioritizing NPL recovery over increasing leverage?', 'ما هي أفضل حجة لإعطاء الأولوية لتحصيل القروض المتعثرة على زيادة الرافعة المالية؟'), options: [
                CaseOption(Bi('DuPont analysis shows NHB already has higher leverage than competitors (5.0 vs. 4.5). The gap is in asset turnover, not leverage. Increasing leverage adds risk without fixing the root inefficiency.', 'يُظهر تحليل ديبونت أن بنك الإسكان الوطني يمتلك بالفعل رافعة مالية أعلى من المنافسين (5.0 مقابل 4.5). الفجوة في معدل دوران الأصول، وليست في الرافعة المالية. وزيادة الرافعة المالية تضيف مخاطر دون معالجة عدم الكفاءة الجذري.'), isCorrect: true, feedback: Bi('Correct! The data-driven argument: NHB\'s equity multiplier is already above peer average. Asset turnover is 33% below benchmark. Adding leverage is the wrong lever - it amplifies risk while leaving unproductive NPLs on the books. DuPont analysis makes this clear.', 'صحيح! الحجة المستندة إلى البيانات: مضاعف حقوق ملكية بنك الإسكان الوطني أعلى بالفعل من متوسط النظراء. ومعدل دوران الأصول أقل من المعيار بنسبة 33%. إن إضافة الرافعة المالية هي الأداة الخاطئة - فهي تضخّم المخاطر بينما تُبقي القروض المتعثرة غير المنتجة في الدفاتر. ويوضح تحليل ديبونت ذلك بجلاء.')),
                CaseOption(Bi('Increasing leverage is illegal for government-owned banks', 'زيادة الرافعة المالية غير قانونية للبنوك المملوكة للدولة'), feedback: Bi('There may be prudential limits, but the argument should be grounded in financial logic (inefficiency of NPLs, not just regulatory constraints).', 'قد تكون هناك حدود احترازية، لكن الحجة ينبغي أن تستند إلى منطق مالي (عدم كفاءة القروض المتعثرة، وليس مجرد القيود التنظيمية).')),
                CaseOption(Bi('NPL recovery is easier to execute than managing increased leverage', 'تحصيل القروض المتعثرة أسهل في التنفيذ من إدارة رافعة مالية متزايدة'), feedback: Bi('This is a weak operational argument. The stronger case is that DuPont analysis reveals asset turnover as the binding constraint, making NPL recovery the correct strategic priority.', 'هذه حجة تشغيلية ضعيفة. الحجة الأقوى هي أن تحليل ديبونت يكشف معدل دوران الأصول باعتباره القيد الملزم، مما يجعل تحصيل القروض المتعثرة الأولوية الاستراتيجية الصحيحة.')),
            ]),
          ]),
      ],
    ),
  ],
);
